async function BURIAL_CHAMBER_DESC(rarg) {
  let offset = (-1), holding = 0, temp_hold = 0;
  if (rarg == M_BEG || rarg == M_LOOK || rarg == M_ENTER) {
    if (eq(loc(BEAM), BURIAL_CHAMBER, NORTH_ANTECHAMBER) && g.BEAM_PLACED) {
      move(BEAM, g.HERE);
    }
  }
  if (!(rarg == M_LOOK)) {
    return false;
  }
  tell("You have entered the Chamber of Departure Towards the Funeral Destinies, the Burial Chamber. There is a doorway leading into a small room off to the east. In the middle of the chamber, stretching almost from wall to wall, is a huge, ancient sarcophagus. Its cover is composed of pure quartz and through the shining light you can see the golden, gleaming mummiform coffin. ");
  await DESCRIBE_COVER();
  loop1: for (;;) {
    offset = offset + 1;
    if (offset > 3) {
      break loop1;
    } else if (hasFlag(get(g.STATUE_TBL, offset), CLAMPBIT)) {
      holding = holding + 1;
    }
  }
  tell(" Four statues surround the sarcophagus, one in each corner: Isis, Nephthys, Neith and Selkis. ");
  if (holding == 4) {
    tell("Their outstretched arms clamp down tightly on the quartz cover.\n");
    return true;
  } else if (holding == 0) {
    tell("All four statues face away from the quartz cover, their grip on it released.\n");
    return true;
  }
  offset = -1;
  temp_hold = holding;
  loop2: for (;;) {
    if (holding == 0) {
      break loop2;
    } else {
      offset = offset + 1;
      if (hasFlag(get(g.STATUE_TBL, offset), CLAMPBIT)) {
        tell(S(get(g.STATUE_NAME_TBL, offset)));
        if (holding > 2) {
          tell(", ");
        } else if (holding > 1) {
          tell(" and ");
        }
        holding = holding - 1;
      }
    }
  }
  if (temp_hold > 1) {
    tell(" are ");
  } else {
    tell(" is ");
  }
  tell("facing inward, ");
  if (temp_hold > 1) {
    tell("their");
  } else {
    tell("its");
  }
  tell(" heavy arms clamping down tightly over the quartz cover of the sarcophagus.\n");
  return true;
}

